From 4c6bfb8780a197be100159ffbf2319192882afd3 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 01:43:24 +0100
Subject: [PATCH] Corona: add closeAppletPopups()

Minimize All Windows hides all windows without moving focus, so applet
popups that close on focus loss stayed open over the desktop. This adds
a Corona call that collapses those popups and keeps pinned ones open.

BUG: 481615
---
 src/plasma/corona.cpp               |  5 +++++
 src/plasma/corona.h                 | 15 +++++++++++++++
 src/plasmaquick/appletquickitem.cpp | 10 ++++++++++
 3 files changed, 30 insertions(+)

diff --git a/src/plasma/corona.cpp b/src/plasma/corona.cpp
index b9f1f83f2..1f187ec22 100644
--- a/src/plasma/corona.cpp
+++ b/src/plasma/corona.cpp
@@ -328,6 +328,11 @@ bool Corona::isEditMode() const
     return d->editMode;
 }

+void Corona::closeAppletPopups()
+{
+    Q_EMIT appletPopupsCloseRequested();
+}
+
 QList<Plasma::Types::Location> Corona::freeEdges(uint screen) const
 {
     QList<Plasma::Types::Location> freeEdges;
diff --git a/src/plasma/corona.h b/src/plasma/corona.h
index e1dd86b91..4679c891f 100644
--- a/src/plasma/corona.h
+++ b/src/plasma/corona.h
@@ -239,6 +239,15 @@ public:
      */
     bool isEditMode() const;

+    /*!
+     * Closes the popups of all applets that close when they lose focus, as
+     * activating the desktop would. Popups that are kept open stay open.
+     *
+     * \sa appletPopupsCloseRequested()
+     * \since 6.9
+     */
+    Q_INVOKABLE void closeAppletPopups();
+
     // TODO: make them not slots anymore
 public Q_SLOTS:
     /*!
@@ -361,6 +370,12 @@ Q_SIGNALS:
      */
     void editModeChanged(bool edit);

+    /*!
+     * Emitted when closeAppletPopups() is called.
+     * \since 6.9
+     */
+    void appletPopupsCloseRequested();
+
     /*!
      * Emitted when the package for this corona has been changed.
      * Shells must support changing the shell package on the fly (for instance due to device form factor changing)
diff --git a/src/plasmaquick/appletquickitem.cpp b/src/plasmaquick/appletquickitem.cpp
index ab3fa7ebb..44395d3ba 100644
--- a/src/plasmaquick/appletquickitem.cpp
+++ b/src/plasmaquick/appletquickitem.cpp
@@ -9,6 +9,7 @@

 #include "appletcontext_p.h"
 #include "containment.h"
+#include "corona.h"
 #include "debug_p.h"
 #include "plasmaquick.h"
 #include "plasmoid/containmentitem.h"
@@ -680,6 +681,15 @@ AppletQuickItem *AppletQuickItem::itemForApplet(Plasma::Applet *applet)
         });
     }

+    if (!applet->isContainment() && applet->containment() && applet->containment()->corona()) {
+        connect(applet->containment()->corona(), &Plasma::Corona::appletPopupsCloseRequested, item, [item]() {
+            // an applet showing its full representation in place has no popup to close
+            if (item->d->expanded && item->d->hideOnWindowDeactivate && item->d->currentRepresentationItem != item->d->fullRepresentationItem) {
+                item->setExpanded(false);
+            }
+        });
+    }
+
     QObject::connect(applet, &Plasma::Applet::appletDeleted, item, [item, thisApplet = applet](Plasma::Applet *applet) {
         if (thisApplet == applet) {
             // appletDelete can also be emitted by a containment for one of its children
-- 
