From 36c1eba648ead109afc2f9264358e24f70173b83 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 01:43:24 +0100
Subject: [PATCH] applets/systemtray: close the popup on Corona's
 closeAppletPopups()

The System Tray manages its own popup, so collapsing applets didn't
close its hidden items view. It now binds hideOnWindowDeactivate to its
pin setting and closes its popup when the shell asks, unless pinned.

BUG: 481615
---
 applets/systemtray/qml/main.qml | 11 +++++++++++
 1 file changed, 11 insertions(+)

diff --git a/applets/systemtray/qml/main.qml b/applets/systemtray/qml/main.qml
index b5cb44ce79..7d3f9c8159 100644
--- a/applets/systemtray/qml/main.qml
+++ b/applets/systemtray/qml/main.qml
@@ -23,6 +23,8 @@ ContainmentItem {
     readonly property bool vertical: Plasmoid.formFactor === PlasmaCore.Types.Vertical
     readonly property bool reverseLayout: Plasmoid.configuration.reverseIconOrder

+    hideOnWindowDeactivate: !Plasmoid.configuration.pin
+
     Layout.minimumWidth: vertical ? Kirigami.Units.iconSizes.small : mainLayout.implicitWidth + Kirigami.Units.smallSpacing
     Layout.minimumHeight: vertical ? mainLayout.implicitHeight + Kirigami.Units.smallSpacing : Kirigami.Units.iconSizes.small

@@ -53,6 +55,15 @@ ContainmentItem {
         }
     }

+    Connections {
+        target: Plasmoid.corona
+        function onAppletPopupsCloseRequested() {
+            if (root.hideOnWindowDeactivate) {
+                systemTrayState.expanded = false;
+            }
+        }
+    }
+
     KItemModels.KSortFilterProxyModel {
         id: activeModel
         filterRoleName: "effectiveStatus"
-- 
